I faced issues while upgrading our Legacy codebase from .NET Framework 4.8 to .NET 8. 

Learned the hard way that .NET Framework 4.8 uses PascalCase Json formatting by default while .NET 8 uses CamelCase. 
Since this is a part of legacy system, updating all the services consuming this project to use CamelCase json deserialization is not possible. 

Since this is missing from System.Text.Json, I had to write my own PascalCase Serializer  

```
    public class PascalCaseJsonNamingPolicy : JsonNamingPolicy
    {
        public override string ConvertName(string name)
        {
            if (string.IsNullOrEmpty(name) || !char.IsLower(name[0]))
            {
                return name;
            }

#if NETCOREAPP
            return string.Create(name.Length, name, (chars, value) =>
            {
                value.CopyTo(chars);
                FixCasing(chars);
            });
#else
            char[] chars = name.ToCharArray();
            FixCasing(chars);
            return new string(chars);
#endif
        }

        private static void FixCasing(Span<char> chars)
        {
            chars[0] = char.ToUpperInvariant(chars[0]);
        }
    }
```

